    if (e.type === 'tool_call') {
      const result = results.get(e.obs_id);
      const command = commandFor(e.name, e.input);
      emit(JSON.stringify({
        type: 'item.started',
        item: { type: 'command_execution', id: e.obs_id, command },
      }) + '\n');
      emit(JSON.stringify({
        type: 'item.completed',
        item: {
          type: 'command_execution',
          id: e.obs_id,
          command,
          aggregated_output: result?.output ?? '',
          exit_code: result?.status === 'error' ? 1 : 0,
          status: result?.status === 'error' ? 'failed' : 'completed',
        },
      }) + '\n');
    } else if (e.type === 'report') {
      agentMessageCount += 1;
      emit(JSON.stringify({
        type: 'item.completed',
        item: { type: 'agent_message', id: `mock-msg-${agentMessageCount}`, text: e.content },
      }) + '\n');
      if (opts.reportFile) await writeFile(opts.reportFile, e.content).catch(() => {});
    }
  }

  emit(JSON.stringify({
    type: 'turn.completed',
    usage: { input_tokens: 0, output_tokens: meta?.total_tokens ?? 0, cached_input_tokens: 0 },
  }) + '\n');
}

// OD-faithful cursor-agent renderer.
//
// Matches the JSONL shape OD's `json-event-stream.ts:handleCursorEvent`
// parser accepts:
//   {"type":"system","subtype":"init","model":"..."}
//   {"type":"assistant","message":{
//      "content":[{"type":"text","text":"..."}, ...]},
//      "timestamp_ms": ...}
//   {"type":"result","usage":{"inputTokens","outputTokens","cacheReadTokens","cacheWriteTokens"},
//      "duration_ms": ...}
//
// Cursor's parser handles delta-vs-replacement detection itself: when a
// later text block STARTS WITH the prior accumulated text, the parser
// strips the prefix and emits only the delta. So we can either emit a
// single message containing the full text, OR emit progressive chunks
// where each chunk is the cumulative-so-far. We use the single-message
// form — simplest, no risk of state desync.
//
// Like gemini, the cursor-agent parser does NOT recognize tool events.
// Tool calls in the recording are ignored; only the final assistant
// text is rendered.

import { writeFile } from 'node:fs/promises';

const sleep = ms => new Promise(r => setTimeout(r, ms));

export async function renderAsCursorAgent(events, opts = {}) {
  const emit = opts.emit ?? (s => process.stdout.write(s));
  const maxSleep = opts.maxSleepMs ?? 2000;
  const meta = events.find(e => e.type === 'meta');

  emit(JSON.stringify({
    type: 'system',
    subtype: 'init',
    model: meta?.model ?? 'cursor-default',
  }) + '\n');

  if (!opts.noDelay) await sleep(Math.min(maxSleep, 200));

  for (const e of events) {
    if (e.type === 'report') {
      emit(JSON.stringify({
        type: 'assistant',
        message: {
          content: [{ type: 'text', text: e.content }],
        },
        timestamp_ms: Date.now(),
      }) + '\n');
      if (opts.reportFile) await writeFile(opts.reportFile, e.content).catch(() => {});
    }
  }

  emit(JSON.stringify({
    type: 'result',
    usage: {
      inputTokens: 0,
      outputTokens: meta?.total_tokens ?? 0,
      cacheReadTokens: 0,
      cacheWriteTokens: 0,
    },
    duration_ms: meta?.duration_ms ?? 0,
  }) + '\n');
}

// OD-faithful gemini renderer.
//
// Matches the JSONL shape OD's `json-event-stream.ts:handleGeminiEvent`
// parser accepts:
//   {"type":"init","model":"..."}                         → status:initializing
//   {"type":"message","role":"assistant","content":"..."}  → text_delta
//   {"type":"tool_use","tool_name":"...","tool_id":"..."}  → tool_use
//   {"type":"tool_result","tool_id":"...","output":"..."}  → tool_result
//   {"type":"result","stats":{...}}                       → usage

import { writeFile } from 'node:fs/promises';

const sleep = ms => new Promise(r => setTimeout(r, ms));

export async function renderAsGemini(events, opts = {}) {
  const emit = opts.emit ?? (s => process.stdout.write(s));
  const maxSleep = opts.maxSleepMs ?? 2000;
  const meta = events.find(e => e.type === 'meta');
  const results = new Map();
  for (const e of events) if (e.type === 'tool_result') results.set(e.obs_id, e);

  emit(JSON.stringify({
    type: 'init',
    model: meta?.model ?? 'gemini-2.5-pro',
  }) + '\n');

  // Stream the report text as one assistant message. Optionally we could
  // chunk by token-count for a more "live streaming" feel — but OD's
  // gemini parser accepts multi-chunk too (each emits as text_delta).
  if (!opts.noDelay) await sleep(Math.min(maxSleep, 200));
  for (const e of events) {
    if (e.type === 'tool_call') {
      const result = results.get(e.obs_id);
      emit(JSON.stringify({
        type: 'tool_use',
        tool_name: e.name,
        tool_id: e.obs_id,
        parameters: e.input ?? null,
      }) + '\n');
      emit(JSON.stringify({
        type: 'tool_result',
        tool_id: e.obs_id,
        status: result?.status === 'error' ? 'error' : 'success',
        output: result?.output ?? '',
      }) + '\n');
    } else if (e.type === 'report') {
      emit(JSON.stringify({
        type: 'message',
        role: 'assistant',
        content: e.content,
      }) + '\n');
      if (opts.reportFile) await writeFile(opts.reportFile, e.content).catch(() => {});
    }
  }

  // Final stats wrapper.
  emit(JSON.stringify({
    type: 'result',
    stats: {
      input_tokens: 0,
      output_tokens: meta?.total_tokens ?? 0,
      cached: 0,
      duration_ms: meta?.duration_ms ?? 0,
    },
  }) + '\n');
}

// OD-faithful kimi renderer.
//
// Matches the JSONL shape OD's `json-event-stream.ts:handleKimiEvent`
// parser accepts:
//   {"role":"assistant","content":"..."}                  → text_delta
//   {"role":"assistant","tool_calls":[...]}               → tool_use
//   {"role":"tool","tool_call_id":"...","content":"..."} → tool_result
//   {"role":"meta","type":"session.resume_hint",...}      → ignored

import { writeFile } from 'node:fs/promises';

const sleep = ms => new Promise(r => setTimeout(r, ms));

export async function renderAsKimi(events, opts = {}) {
  const emit = opts.emit ?? (s => process.stdout.write(s));
  const maxSleep = opts.maxSleepMs ?? 2000;
  const meta = events.find(e => e.type === 'meta');
  const results = new Map();
  for (const e of events) if (e.type === 'tool_result') results.set(e.obs_id, e);

  if (!opts.noDelay) await sleep(Math.min(maxSleep, 200));

  for (const e of events) {
    if (e.type === 'tool_call') {
      const result = results.get(e.obs_id);
      emit(JSON.stringify({
        role: 'assistant',
        tool_calls: [
          {
            type: 'function',
            id: e.obs_id,
            function: {
              name: e.name,
              arguments: JSON.stringify(e.input ?? null),
            },
          },
        ],
      }) + '\n');
      emit(JSON.stringify({
        role: 'tool',
        tool_call_id: e.obs_id,
        content: result?.output ?? '',
      }) + '\n');
      continue;
    }
    if (e.type === 'report') {
      emit(JSON.stringify({
        role: 'assistant',
        content: e.content,
      }) + '\n');
      emit(JSON.stringify({
        role: 'meta',
        type: 'session.resume_hint',
        session_id: meta?.session_id ?? `mock-${Date.now()}`,
        content: 'To resume this session: kimi -r mock-session',
      }) + '\n');
      if (opts.reportFile) await writeFile(opts.reportFile, e.content).catch(() => {});
    }
  }
}

// OD-faithful opencode renderer. Emits the JSONL shape OD's
// `json-event-stream.ts:handleOpenCodeEvent` parser accepts.

import { writeFile } from 'node:fs/promises';

const sleep = ms => new Promise(r => setTimeout(r, ms));

export async function renderAsOpencode(events, opts = {}) {
  const emit = opts.emit ?? (s => process.stdout.write(s));
  const maxSleep = opts.maxSleepMs ?? 3000;
  const sessionId = opts.sessionId ?? `mock-${Date.now()}`;
  const meta = events.find(e => e.type === 'meta');

  const results = new Map();
  for (const e of events) if (e.type === 'tool_result') results.set(e.obs_id, e);

  emit(JSON.stringify({ type: 'step_start' }) + '\n');

  let lastT = 0;
  for (const e of events) {
    if (e.type === 'meta' || e.type === 'stdout' || e.type === 'tool_result') continue;
    const t = typeof e.t_ms === 'number' ? e.t_ms : undefined;
    if (!opts.noDelay && t !== undefined) {
      const delta = Math.min(maxSleep, Math.max(0, t - lastT));
      if (delta > 0) await sleep(delta);
      lastT = t;
    }
    if (e.type === 'tool_call') {
      const result = results.get(e.obs_id);
      const isErr = result?.status === 'error';
      emit(JSON.stringify({
        type: 'tool_use',
        sessionID: sessionId,
        part: {
          tool: e.name,
          callID: e.obs_id,
          state: {
            input: e.input ?? null,
            status: isErr ? 'failed' : 'completed',
            output: result?.output ?? '',
          },
        },
      }) + '\n');
    } else if (e.type === 'report') {
      emit(JSON.stringify({
        type: 'text',
        part: { text: e.content },
      }) + '\n');
      if (opts.reportFile) await writeFile(opts.reportFile, e.content).catch(() => {});
    }
  }

  emit(JSON.stringify({
    type: 'step_finish',
    part: {
      tokens: { input: 0, output: meta?.total_tokens ?? 0, reasoning: 0, cache: { read: 0, write: 0 } },
      cost: 0,
    },
  }) + '\n');
}

// Plain (raw stdout) renderer. OD's `plain` streamFormat (deepseek /
// qwen / grok / grok-build) treats stdout as the final assistant
// response. We emit ONLY the report content.

import { writeFile } from 'node:fs/promises';

const sleep = ms => new Promise(r => setTimeout(r, ms));

export async function renderAsPlain(events, opts = {}) {
  const emit = opts.emit ?? (s => process.stdout.write(s));
  const maxSleep = opts.maxSleepMs ?? 2000;

  if (opts.includeToolTrace) {
    const tools = events.filter(e => e.type === 'tool_call');
    if (tools.length > 0) {
      emit(`<!-- tools used (${tools.length}):\n`);
      for (const tc of tools) {
        const summary = (() => {
          if (!tc.input || typeof tc.input !== 'object') return '';
          const o = tc.input;
          if (typeof o.file_path === 'string') return o.file_path;
          if (typeof o.command === 'string') return o.command;
          if (typeof o.pattern === 'string') return `${o.pattern} in ${o.path ?? '.'}`;
          return JSON.stringify(o).slice(0, 80);
        })();
        emit(`  ${tc.name} ${summary}\n`);
      }
      emit(`-->\n`);
    }
  }

  for (const e of events) {
    if (e.type === 'report') {
      if (!opts.noDelay) await sleep(Math.min(maxSleep, 200));
      emit(e.content);
      if (!e.content.endsWith('\n')) emit('\n');
      if (opts.reportFile) await writeFile(opts.reportFile, e.content).catch(() => {});
    }
  }
}

// OD-faithful vela renderer for AMR (Agent Management Runtime).
//
// vela is the bin OD's AMR runtime spawns; `bin: 'vela'` in
// apps/daemon/src/runtimes/defs/amr.ts. The protocol is ACP JSON-RPC
// over stdio, but vela's spec extends the generic ACP shape with:
//
//   1. `initialize` response carries `agentCapabilities` and `models`
//      (currentModelId + availableModels).
//   2. `session/new` response carries the same `models` block.
//   3. `session/prompt` is REJECTED unless `session/set_model` (or
//      `session/set_config_option`) has been called for the current
//      sessionId — the strict-set_model gate. This is the contract real
//      vela 0.0.1 enforces; we mirror it so a regression in
//      attachAcpSession that silently skips set_model gets caught.
//   4. Final prompt response includes `usage.{inputTokens, outputTokens,
//      totalTokens}` (no cachedReadTokens — vela doesn't surface those).
//
// Error-injection envs (mirror apps/daemon/tests/fixtures/fake-vela.mjs):
//   FAKE_VELA_SESSION_NEW_ERROR — fail session/new with this message
//   FAKE_VELA_SET_MODEL_ERROR   — fail session/set_model
//   FAKE_VELA_PROMPT_ERROR      — fail session/prompt
//   FAKE_VELA_REQUIRE_SET_MODEL='0' — disable the strict gate (legacy)
//
// Content envs:
//   FAKE_VELA_SESSION_ID  — the sessionId returned by session/new
//   FAKE_VELA_TEXT        — override the assistant text (defaults to recording's
//                           report content)
//   FAKE_VELA_THOUGHT     — optional thought_chunk emitted before text

import { writeFile } from 'node:fs/promises';

const PROTOCOL_VERSION = 1;
const sleep = ms => new Promise(r => setTimeout(r, ms));

const DEFAULT_AVAILABLE_MODELS = [
  { modelId: 'openai/gpt-5.4-mini',         name: 'gpt-5.4-mini' },
  { modelId: 'anthropic/claude-3.7-sonnet', name: 'claude-3.7-sonnet' },
  { modelId: 'deepseek-v3.2',               name: 'deepseek-v3.2' },
  { modelId: 'glm-5.1',                     name: 'glm-5.1' },
];

function writeRpcResult(out, id, result) {
  out.write(JSON.stringify({ jsonrpc: '2.0', id, result }) + '\n');
}

function writeRpcError(out, id, message, code = -32603) {
  out.write(JSON.stringify({ jsonrpc: '2.0', id, error: { code, message } }) + '\n');
}

function writeNotification(out, method, params) {
  out.write(JSON.stringify({ jsonrpc: '2.0', method, params }) + '\n');
}

/** Split long text on word boundaries — chunk size mirrors the real vela
 *  agent server's typical streaming cadence (the existing fake-vela.mjs
 *  uses 16-char chunks; we use 400 to match the higher-throughput
 *  recordings without flooding the test harness). */
function chunkText(text, target = 400) {
  if (text.length <= target) return [text];
  const chunks = [];
  let pos = 0;
  while (pos < text.length) {
    let end = Math.min(text.length, pos + target);
    if (end < text.length) {
      const ws = text.indexOf(' ', end);
      if (ws !== -1 && ws - end < 200) end = ws + 1;
    }
    chunks.push(text.slice(pos, end));
    pos = end;
  }
  return chunks;
}

/**
 * Run the vela ACP server on stdin/stdout. Returns a promise that
 * resolves when stdin closes or the prompt round-trip completes.
 */
export async function runVelaAcpServer(events, opts = {}) {
  const out = opts.emit ?? process.stdout;
  const meta = events.find(e => e.type === 'meta');
  const reportEvent = events.find(e => e.type === 'report');
  const reportText = process.env.FAKE_VELA_TEXT ?? reportEvent?.content ?? '';
  const thoughtText = process.env.FAKE_VELA_THOUGHT ?? '';

  const sessionId = opts.sessionId ?? process.env.FAKE_VELA_SESSION_ID ?? `fake-vela-session-${Date.now()}`;
  const strict = process.env.FAKE_VELA_REQUIRE_SET_MODEL !== '0';
  const SESSION_NEW_ERROR = process.env.FAKE_VELA_SESSION_NEW_ERROR ?? '';
  const SET_MODEL_ERROR   = process.env.FAKE_VELA_SET_MODEL_ERROR   ?? '';
  const PROMPT_ERROR      = process.env.FAKE_VELA_PROMPT_ERROR      ?? '';

  let currentModelId = null;
  const sessionsWithModel = new Set();
  let buf = '';
  let aborted = false;

  const startPromptResponse = async (id, sid) => {
    if (thoughtText) {
      writeNotification(out, 'session/update', {
        sessionId: sid,
        update: {
          sessionUpdate: 'agent_thought_chunk',
          content: { type: 'text', text: thoughtText },
        },
      });
    }
    const chunks = chunkText(reportText, 400);
    for (const chunk of chunks) {
      if (aborted) break;
      if (!opts.noDelay) await sleep(30);
      writeNotification(out, 'session/update', {
        sessionId: sid,
        update: {
          sessionUpdate: 'agent_message_chunk',
          content: { type: 'text', text: chunk },
        },
      });
    }
    writeRpcResult(out, id, {
      stopReason: 'end_turn',
      usage: {
        inputTokens: 12,
        outputTokens: meta?.total_tokens ?? 7,
        totalTokens: (meta?.total_tokens ?? 7) + 12,
      },
    });
    if (opts.reportFile) await writeFile(opts.reportFile, reportText).catch(() => {});
  };

  const handleRpc = async (obj) => {
    if (!obj || typeof obj !== 'object') return;
    const { id, method, params } = obj;
    switch (method) {
      case 'initialize':
        writeRpcResult(out, id, {
          protocolVersion: PROTOCOL_VERSION,
          agentCapabilities: { promptCapabilities: { embeddedContext: false } },
          models: {
            currentModelId,
            availableModels: DEFAULT_AVAILABLE_MODELS,
          },
        });
        return;
      case 'session/new': {
        if (SESSION_NEW_ERROR) {
          writeRpcError(out, id, SESSION_NEW_ERROR);
          return;
        }
        writeRpcResult(out, id, {
          sessionId,
          models: { currentModelId, availableModels: DEFAULT_AVAILABLE_MODELS },
        });
        return;
      }
      case 'session/set_model': {
        if (SET_MODEL_ERROR) {
          writeRpcError(out, id, SET_MODEL_ERROR, -32099);
          return;
        }
        const next = typeof params?.modelId === 'string' ? params.modelId.trim() : '';
        const sid = typeof params?.sessionId === 'string' ? params.sessionId : sessionId;
        if (next) currentModelId = next;
        sessionsWithModel.add(sid);
        writeRpcResult(out, id, {});
        return;
      }
      case 'session/set_config_option': {
        // Treat config-option model selection as set_model for the
        // strict-set_model gate.
        const sid = typeof params?.sessionId === 'string' ? params.sessionId : sessionId;
        sessionsWithModel.add(sid);
        writeRpcResult(out, id, {});
        return;
      }
      case 'session/prompt': {
        if (PROMPT_ERROR) {
          writeRpcError(out, id, PROMPT_ERROR, -32602);
          return;
        }
        const sid = typeof params?.sessionId === 'string' ? params.sessionId : sessionId;
        if (strict && !sessionsWithModel.has(sid)) {
          writeRpcError(out, id, 'session/set_model must be called before session/prompt', -32602);
          return;
        }
        void startPromptResponse(id, sid);
        return;
      }
      case 'session/cancel':
        aborted = true;
        return;
      default:
        if (id !== undefined && id !== null) {
          writeRpcError(out, id, `unknown method: ${method}`, -32601);
        }
    }
  };

  return new Promise((resolve) => {
    process.stdin.setEncoding('utf-8');
    process.stdin.on('data', async (data) => {
      buf += data;
      let nl;
      while ((nl = buf.indexOf('\n')) !== -1) {
        const line = buf.slice(0, nl).trim();
        buf = buf.slice(nl + 1);
        if (!line) continue;
        let obj;
        try { obj = JSON.parse(line); } catch { continue; }
        await handleRpc(obj);
      }
    });
    process.stdin.on('end', () => resolve());
    process.stdin.on('error', () => resolve());

    const onSig = () => { aborted = true; resolve(); };
    process.once('SIGINT', onSig);
    process.once('SIGTERM', onSig);

    // 30s safety timeout; .unref() so a completed session exits promptly.
    setTimeout(() => {
      process.stderr.write('[mock-vela] no prompt received within 30s; exiting\n');
      resolve();
    }, 30_000).unref();
  });
}

// Pick which recording to play back, driven by env vars.
//
// Priority order:
//   1. OD_MOCKS_TRACE                → fixed trace id (or prefix)
//   2. OD_MOCKS_BY_PROMPT_HASH=1     → hash(prompt) → trace
//   3. OD_MOCKS_POOL=<tag>           → random within tag pool
//   4. (default)                                → random across all
//
// OD_MOCKS_SEED gives reproducible "random" selection.
// OD_MOCKS_RECORDINGS_DIR overrides the default recordings dir
// (defaults to ../recordings/ relative to this file).

import { readdir, readFile, stat } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
export const DEFAULT_RECORDINGS_DIR =
  process.env.OD_MOCKS_RECORDINGS_DIR ||
  join(HERE, '..', 'recordings');

async function listRecordings(dir) {
  try {
    return (await readdir(dir))
      .filter(f => f.endsWith('.jsonl'))
      .map(f => f.replace(/\.jsonl$/, ''))
      .sort();
  } catch {
    return [];
  }
}

async function readMeta(dir, traceId) {
  try {
    const txt = await readFile(join(dir, `${traceId}.jsonl`), 'utf-8');
    const firstLine = txt.split('\n', 1)[0];
    return JSON.parse(firstLine);
  } catch {
    return null;
  }
}

function pickRandom(arr, seed) {
  if (arr.length === 0) return null;
  if (!seed) return arr[Math.floor(Math.random() * arr.length)];
  const h = parseInt(createHash('sha256').update(String(seed)).digest('hex').slice(0, 12), 16);
  return arr[h % arr.length];
}

export async function pickRecording({ prompt } = {}) {
  const dir = DEFAULT_RECORDINGS_DIR;
  const all = await listRecordings(dir);
  if (all.length === 0) return null;

  // 1. fixed — if the env is set, refuse to fall through to random / pool /
  //    hash selection. A typo in `OD_MOCKS_TRACE` should surface loudly,
  //    not silently produce a different trace and silently poison a test.
  const fixed = process.env.OD_MOCKS_TRACE;
  if (fixed) {
    const hit = all.find(id => id === fixed) ?? all.find(id => id.startsWith(fixed));
    if (hit) return { traceId: hit, path: join(dir, `${hit}.jsonl`), method: 'fixed' };
    throw new Error(
      `OD_MOCKS_TRACE="${fixed}" set but no matching recording in ${dir}. ` +
      `8-char id prefix is supported; check spelling and that the corpus has been fetched ` +
      `(\`bash mocks/scripts/fetch-recordings.sh\`).`
    );
  }

  // 2. prompt-hash
  if (process.env.OD_MOCKS_BY_PROMPT_HASH === '1' && prompt) {
    const picked = pickRandom(all, prompt);
    if (picked) return { traceId: picked, path: join(dir, `${picked}.jsonl`), method: 'hash' };
  }

  // 3. pool by tag — supports structured `<dimension>:<value>` shortcuts
  //    documented in README (agent:claude, skill:agent-browser,
  //    outcome:failed). The dimension routes to the right meta field;
  //    bare values fall back to tag substring match. Mirrors the
  //    OD_MOCKS_TRACE policy: if the env is set and matches nothing,
  //    refuse to fall through to global random — surface the typo.
  const pool = process.env.OD_MOCKS_POOL;
  if (pool) {
    const colonIdx = pool.indexOf(':');
    const dim = colonIdx >= 0 ? pool.slice(0, colonIdx) : null;
    const value = colonIdx >= 0 ? pool.slice(colonIdx + 1) : null;

    const candidates = [];
    for (const id of all) {
      const meta = await readMeta(dir, id);
      if (!meta) continue;
      const tags = meta.tags ?? [];

      let match = false;
      if (dim === 'outcome' && meta.outcome === value)               match = true;
      else if (dim === 'agent'  && meta.agent === value)             match = true;
      else if (dim === 'skill'  && tags.some(t => t === `skill:${value}`)) match = true;
      else if (tags.includes(pool))                                  match = true;
      else if (meta.agent === pool)                                  match = true;
      else if (tags.some(t => typeof t === 'string' && t.includes(pool))) match = true;

      if (match) candidates.push(id);
    }
    if (candidates.length === 0) {
      throw new Error(
        `OD_MOCKS_POOL="${pool}" matched no recordings in ${dir}. ` +
        `Supported shapes: agent:<name>, skill:<name>, outcome:<succeeded|failed|errored>, ` +
        `or any tag substring. Check candidates with ` +
        `\`jq '[.entries[] | {agent, outcome, skills}] | unique' mocks/manifest.json\`.`,
      );
    }
    const picked = pickRandom(candidates, process.env.OD_MOCKS_SEED);
    if (picked) return { traceId: picked, path: join(dir, `${picked}.jsonl`), method: 'pool', pool };
  }

  // 4. random
  const picked = pickRandom(all, process.env.OD_MOCKS_SEED);
  if (!picked) return null;
  return { traceId: picked, path: join(dir, `${picked}.jsonl`), method: 'random' };
}

export async function readRecording(path) {
  const text = await readFile(path, 'utf-8');
  return text
    .split('\n')
    .filter(Boolean)
    .map(line => JSON.parse(line));
}

// vela subcommand handlers (login + models) used by the mock CLI when
// argv[1] is not the default 'agent' (which falls through to the
// ACP server in format-vela.mjs).
//
// Mirrors the contract that
// apps/daemon/tests/fixtures/fake-vela.mjs implements — kept in sync
// because both feed the same daemon-side login route + status reader
// (apps/daemon/src/integrations/vela-profile.ts +
// apps/web/src/components/amrLoginPolling.ts).

import { mkdirSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { dirname, join } from 'node:path';

const DEFAULT_MODELS_STDOUT = [
  'public_model_deepseek_v3_2          vela',
  'public_model_deepseek_v4_flash      vela',
  'public_model_deepseek_v4_pro        vela',
  'public_model_gemini_2_5_flash       vela',
  'public_model_gemini_3_1_flash_lite_preview  vela',
  'public_model_gemini_3_1_pro_preview vela',
  'public_model_gpt_5_4                vela',
  'public_model_gpt_5_4_mini           vela',
  'public_model_glm_5                  vela',
  'public_model_glm_5_1                vela',
  'public_model_gpt_image_2            vela',
  'public_model_kimi_k2_6              vela',
  'public_model_minimax_m2_7           vela',
  'public_model_qwen3_235b_a22b        vela',
  'public_model_seedance_2             vela',
].join('\n');

/**
 * `vela login` — writes the AMR config file the daemon's status reader
 * + AmrLoginPill component expect on disk. The real vela goes through a
 * device-authorization browser approval; we skip the loop and just
 * project the same on-disk artifact a successful real login produces.
 *
 * Envs (compat with fake-vela.mjs):
 *   VELA_PROFILE                — profile slot to populate (prod|test|local)
 *   FAKE_VELA_LOGIN_DELAY_MS    — sleep before the write (test in-flight states)
 *   FAKE_VELA_LOGIN_USER_EMAIL  — email written into the profile
 *   FAKE_VELA_LOGIN_USER_PLAN   — plan written into the profile
 *   FAKE_VELA_LOGIN_FAIL        — when set, prints to stderr + exits 1
 */
export async function runVelaLogin() {
  if (process.env.FAKE_VELA_LOGIN_FAIL) {
    process.stderr.write(`${process.env.FAKE_VELA_LOGIN_FAIL}\n`);
    process.exit(1);
  }
  const allowed = new Set(['prod', 'test', 'local']);
  const requested = (process.env.VELA_PROFILE || 'prod').trim() || 'prod';
  const profile = allowed.has(requested) ? requested : 'prod';
  if (!allowed.has(requested)) {
    process.stderr.write(`[mock-vela] unknown profile ${requested}; defaulting to prod\n`);
  }
  const delayMs = Number(process.env.FAKE_VELA_LOGIN_DELAY_MS) || 0;
  const userEmail = process.env.FAKE_VELA_LOGIN_USER_EMAIL || 'fake-user@example.com';
  const userPlan  = process.env.FAKE_VELA_LOGIN_USER_PLAN  || 'free';

  const write = () => {
    const file = join(homedir(), '.amr', 'config.json');
    mkdirSync(dirname(file), { recursive: true });
    const payload = {
      profiles: {
        [profile]: {
          // Fake credentials — never used by real vela traffic since the
          // daemon's link client points at the same FAKE_VELA_API_URL.
          controlKey: 'fake-control-key-0000000000000000000000',
          runtimeKey: 'fake-runtime-key-0000000000000000000000',
          apiUrl:  profile === 'local' ? 'http://localhost:18080' : '',
          linkUrl: profile === 'local' ? 'http://localhost:18081' : '',
          user: {
            id: 'fake-user-id',
            email: userEmail,
            name: 'Fake User',
            plan: userPlan,
          },
        },
      },
    };
    writeFileSync(file, JSON.stringify(payload, null, 2), 'utf8');
    process.stdout.write(`Login successful for ${userEmail}.\n`);
    process.exit(0);
  };

  if (delayMs > 0) setTimeout(write, delayMs);
  else write();
}

/**
 * `vela models` — prints the production-shaped public model catalog.
 * Override via FAKE_VELA_MODELS env (newline-separated lines).
 */
export function runVelaModels() {
  const out = process.env.FAKE_VELA_MODELS || DEFAULT_MODELS_STDOUT;
  process.stdout.write(`${out}\n`);
  process.exit(0);
}

#!/usr/bin/env node
/**
 * mock-agent.mjs — pretends to be one of OD's supported agent CLIs
 * (claude / opencode / codex / deepseek / qwen / grok) by streaming a
 * pre-recorded session in that CLI's native stdout protocol. Zero LLM
 * tokens.
 *
 * Usage (driven by the wrappers in bin/, not directly):
 *   ./mock-agent.mjs --as opencode [--no-delay] [--report-file <path>]
 *
 * Recording selection — see lib/recording-picker.mjs. The wrappers
 * announce the picked trace id on stderr.
 *
 * Trace data: ./recordings/<trace-id>.jsonl (anonymized exports from
 * Langfuse). Index: ./recordings/index.json.
 */

import { pickRecording, readRecording } from './lib/recording-picker.mjs';
import { renderAsOpencode }    from './lib/format-opencode.mjs';
import { renderAsCodex }       from './lib/format-codex.mjs';
import { renderAsClaude }      from './lib/format-claude.mjs';
import { renderAsGemini }      from './lib/format-gemini.mjs';
import { renderAsCursorAgent } from './lib/format-cursor-agent.mjs';
import { renderAsKimi }        from './lib/format-kimi.mjs';
import { renderAsPlain }       from './lib/format-plain.mjs';
import { runAcpServer }        from './lib/format-acp.mjs';
import { runVelaAcpServer }    from './lib/format-vela.mjs';
import { runVelaLogin, runVelaModels } from './lib/vela-subcommands.mjs';

function parseArgs(argv) {
  const opts = { as: null, noDelay: false, reportFile: null, positionals: [] };
  const flagsWithValue = new Set(['--as', '--agent', '--report-file', '-p', '--output-format', '--model', '-r']);
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--as' || a === '--agent') { opts.as = argv[++i]; continue; }
    if (a === '--no-delay')              { opts.noDelay = true; continue; }
    if (a === '--report-file')           { opts.reportFile = argv[++i]; continue; }
    if (flagsWithValue.has(a))           { i++; continue; }
    if (a.startsWith('-')) continue;     // Unknown flag — silently skip (model/permission flags etc.)
    // Anything left is a positional — used by vela subcommand dispatch.
    opts.positionals.push(a);
  }
  if (process.env.OD_MOCKS_NO_DELAY === '1') opts.noDelay = true;
  // Fall through to REPORT_FILE env when --report-file wasn't supplied.
  // Some harnesses (e.g. the agent-pr-explore orchestrator) set
  // REPORT_FILE as env but expect the agent to write there
  // autonomously — real opencode/claude do via their Write tool, but
  // the mock needs to project the recording's final assistant text to
  // that path so the harness sees a report.
  if (!opts.reportFile && process.env.REPORT_FILE) {
    opts.reportFile = process.env.REPORT_FILE;
  }
  return opts;
}

function failUsage(message) {
  process.stderr.write(`mock-agent: ${message}\n`);
  process.exit(2);
}

async function readStdinIfPiped() {
  if (process.stdin.isTTY) return '';
  return new Promise(resolve => {
    let acc = '';
    process.stdin.setEncoding('utf-8');
    process.stdin.on('data', c => { acc += c; });
    process.stdin.on('end',  () => resolve(acc));
    process.stdin.on('error', () => resolve(acc));
    // Safety timeout in case the parent never closes stdin (PTY).
    setTimeout(() => resolve(acc), 1500);
  });
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));
  if (!opts.as) {
    failUsage(
      '--as <agent> required\n' +
      '  supported: opencode | claude | amp | codex | gemini | cursor-agent |\n' +
      '             deepseek | qwen | grok | plain |\n' +
      '             kimi                                         (stream-json)\n' +
      '             devin | hermes | kilo | kiro | vibe          (ACP)\n' +
      '             vela                                          (AMR — vela CLI)\n',
    );
  }

  // `vela` dispatches by the first positional arg passed by OD (login /
  // models / agent). Subcommands run BEFORE recording selection because
  // they don't use trace data at all.
  if (opts.as === 'vela') {
    const cmd = (opts.positionals[0] || '').trim();
    if (cmd === 'login')  return runVelaLogin();
    if (cmd === 'models') return runVelaModels();
    // Default: `agent run --runtime opencode` — fall through to the ACP
    // server below with the vela-flavored protocol.
  }

  // Modern Kimi rejects the old `kimi acp ...` launch shape; keep the
  // shared mock aligned so adapter regressions fail fast in tests.
  if (opts.as === 'kimi' && opts.positionals.length > 0) {
    failUsage(`too many arguments: ${opts.positionals.join(' ')}`);
  }

  // ACP agents read JSON-RPC messages off stdin one line at a time, so the
  // bulk-prompt buffering logic below doesn't apply — pickRecording sees no
  // prompt for hash-mode (use OD_MOCKS_TRACE or _POOL instead).
  const ACP_AGENTS = new Set(['devin', 'hermes', 'kilo', 'kiro', 'vibe', 'vela']);
  const isAcp = ACP_AGENTS.has(opts.as);
  const prompt = isAcp ? '' : await readStdinIfPiped();
  const picked = await pickRecording({ prompt });
  if (!picked) {
    process.stderr.write(
      'mock-agent: no recordings on disk yet.\n' +
      'The recording corpus is hosted on Cloudflare R2 (see mocks/manifest.json)\n' +
      'and is fetched on demand. Run:\n' +
      '\n' +
      '  bash mocks/scripts/fetch-recordings.sh             # all 179 (~30s, 4.5MB)\n' +
      '  bash mocks/scripts/fetch-recordings.sh --agent claude   # subset\n' +
      '\n' +
      'Or set OD_MOCKS_RECORDINGS_DIR if you stashed them elsewhere.\n',
    );
    process.exit(3);
  }

  process.stderr.write(
    `[mock-${opts.as}] picked ${picked.traceId.slice(0, 8)}… via ${picked.method}` +
    (picked.pool ? ` (pool="${picked.pool}")` : '') +
    '\n',
  );

  const events = await readRecording(picked.path);
  const renderOpts = { noDelay: opts.noDelay, reportFile: opts.reportFile };

  switch (opts.as) {
    case 'opencode':     await renderAsOpencode(events, renderOpts);    break;
    case 'codex':        await renderAsCodex(events, renderOpts);       break;
    case 'claude':
    case 'amp':          await renderAsClaude(events, renderOpts);      break;
    case 'gemini':       await renderAsGemini(events, renderOpts);      break;
    case 'cursor-agent': await renderAsCursorAgent(events, renderOpts); break;
    case 'deepseek':
    case 'qwen':
    case 'grok':
    case 'plain':        await renderAsPlain(events, renderOpts);       break;
    case 'kimi':         await renderAsKimi(events, renderOpts);        break;
    // ACP family — JSON-RPC server over stdio.
    case 'devin':
    case 'hermes':
    case 'kilo':
    case 'kiro':
    case 'vibe':         await runAcpServer(events, renderOpts);        break;
    // AMR (vela CLI) — ACP with vela-specific protocol extensions
    // (agentCapabilities + models block + strict set_model gate).
    case 'vela':         await runVelaAcpServer(events, renderOpts);    break;
    default:
      failUsage(`unknown agent "${opts.as}"`);
  }
}

main().catch(err => {
  process.stderr.write(`mock-agent: ${err.message}\n`);
  process.exit(1);
});

// Manifest math — shared between the local `add-recording.sh` preview
// step and the GitHub Action that actually does R2 uploads.
//
// Concentrated here so a maintainer who eyeballs add-recording's
// preview output sees the SAME entry shape the workflow will commit
// post-merge. No drift.

import { readFileSync as readSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { basename } from 'node:path';

/**
 * Parse a recording's first JSONL line (the `meta` event) and return
 * the shape we store in the manifest.
 */
export function inspectRecording(jsonlPath) {
  const buf = readSync(jsonlPath);
  const sha256 = createHash('sha256').update(buf).digest('hex');
  const firstLine = buf.toString('utf-8').split('\n', 1)[0];
  let meta;
  try {
    meta = JSON.parse(firstLine);
  } catch (err) {
    throw new Error(`first line of ${jsonlPath} is not valid JSON: ${err.message}`);
  }
  if (meta.type !== 'meta') {
    throw new Error(`first line of ${jsonlPath} has type="${meta.type}" — expected "meta"`);
  }
  const traceId = basename(jsonlPath, '.jsonl');
  const skills = (meta.tags ?? [])
    .filter(t => typeof t === 'string' && t.startsWith('skill:'))
    .map(t => t.slice('skill:'.length));
  return {
    trace_id: traceId,
    sha256,
    bytes: buf.byteLength,
    agent: meta.agent ?? 'unknown',
    model: meta.model ?? null,
    outcome: meta.outcome ?? 'unknown',
    tool_count: meta.tool_call_count ?? 0,
    duration_ms: meta.duration_ms ?? 0,
    skills: skills.length > 0 ? skills : ['default'],
    session_id: meta.session_id ?? null,
    user_input_preview: meta.user_input
      ? String(meta.user_input).slice(0, 200).replace(/\s+/g, ' ').trim()
      : null,
    multi_turn: false,                    // filled in after histograms
    // ──── Provenance (fixture-trust signals; mrcfps review #3241) ────
    // Capture-time fields the harvester writes into the meta event.
    // Older recordings may not have them all — null is the explicit "we
    // don't know" so consumers can decide whether the fixture is still
    // trustworthy as the real CLIs evolve.
    captured_at: meta.timestamp ?? null,            // ISO 8601 of the original session
    cli_version: meta.cli_version ?? null,          // e.g. "claude-code 1.0.65" / "codex 0.40"
    protocol_version: meta.protocol_version ?? null,
    anonymization_version: meta.anonymization_version ?? null,
  };
}

/**
 * Insert / replace a manifest entry and rebuild all derived fields
 * (histograms, multi_turn flags, total_bytes, total). Returns the
 * mutated manifest object — caller writes it back if it wants to.
 */
export function upsertEntry(manifest, newEntry) {
  const idx = manifest.entries.findIndex(e => e.trace_id === newEntry.trace_id);
  if (idx >= 0) {
    manifest.entries[idx] = newEntry;
  } else {
    manifest.entries.push(newEntry);
  }
  // Rebuild derived fields from scratch.
  const byAgent = {};
  const byOutcome = {};
  const bySkill = {};
  const sessions = {};
  let totalBytes = 0;
  for (const e of manifest.entries) {
    byAgent[e.agent] = (byAgent[e.agent] ?? 0) + 1;
    byOutcome[e.outcome] = (byOutcome[e.outcome] ?? 0) + 1;
    for (const s of e.skills) bySkill[s] = (bySkill[s] ?? 0) + 1;
    if (e.session_id) (sessions[e.session_id] ??= []).push(e.trace_id);
    totalBytes += e.bytes;
  }
  for (const e of manifest.entries) {
    e.multi_turn = !!(e.session_id && (sessions[e.session_id]?.length ?? 0) >= 2);
  }
  manifest.entries.sort((a, b) => a.trace_id.localeCompare(b.trace_id));
  manifest.generated_at = new Date().toISOString();
  manifest.total = manifest.entries.length;
  manifest.total_bytes = totalBytes;
  manifest.histograms = { by_agent: byAgent, by_outcome: byOutcome, by_skill: bySkill };
  manifest.sessions_with_multi_turn = Object.values(sessions).filter(s => s.length >= 2).length;
  return manifest;
}

export function readManifest(path) {
  return JSON.parse(readSync(path, 'utf-8'));
}

export function writeManifest(path, manifest) {
  writeFileSync(path, JSON.stringify(manifest, null, 2));
}
